<?php endif; ?></div></div></div></div><script>(function(){var toggle=document.getElementById('scr-goal-staff-toggle'),menu=document.getElementById('scr-goal-staff-menu');if(!toggle||!menu)return;var checks=Array.prototype.slice.call(menu.querySelectorAll('input[type=checkbox]')),count=document.getElementById('scr-goal-selected-count'),search=document.getElementById('scr-goal-staff-search');function update(){var n=checks.filter(function(x){return x.checked}).length;count.textContent=n?n+' نفر انتخاب شده‌اند':'هیچ فردی انتخاب نشده است';toggle.textContent=n?n+' نفر انتخاب شده‌اند':'انتخاب کارشناسان یا مدیران';}toggle.addEventListener('click',function(){var open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',open?'true':'false');});document.getElementById('scr-goal-select-all').addEventListener('click',function(){checks.forEach(function(x){if(x.closest('label').style.display!=='none')x.checked=true});update()});document.getElementById('scr-goal-clear-all').addEventListener('click',function(){checks.forEach(function(x){x.checked=false});update()});checks.forEach(function(x){x.addEventListener('change',update)});search.addEventListener('input',function(){var q=this.value.trim().toLowerCase();checks.forEach(function(x){var label=x.closest('label');label.style.display=label.textContent.toLowerCase().indexOf(q)>=0?'flex':'none'})});document.addEventListener('click',function(e){if(!menu.contains(e.target)&&e.target!==toggle){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});var form=toggle.closest('form');form.addEventListener('submit',function(e){if(!checks.some(function(x){return x.checked})){e.preventDefault();alert('حداقل یک کارمند انتخاب کنید')}});update()})();</script><script>(function(){var role='seller',type='all',r=document.getElementById('scr-goal-role-tabs'),t=document.getElementById('scr-goal-type-tabs');if(!r||!t)return;function draw(){var count=0;document.querySelectorAll('.scr-goal-tab-content.active table.scr-goal-table tbody tr[data-goal-role]').forEach(function(tr){var visible=tr.getAttribute('data-goal-role')===role&&(type==='all'||tr.getAttribute('data-goal-type')===type);tr.style.display=visible?'':'none';if(visible)count++});var e=document.getElementById('scr-goal-filter-empty');if(e)e.style.display=count?'none':'block';}[[r,'role'],[t,'type']].forEach(function(x){x[0].addEventListener('click',function(e){var b=e.target.closest('button[data-'+x[1]+']');if(!b)return;x[0].querySelectorAll('button').forEach(function(z){z.classList.remove('active')});b.classList.add('active');if(x[1]==='role')role=b.dataset.role;else type=b.dataset.type;draw()})});draw()})();</script><?php init_tail(); ?>
